import graph; size(4cm);
fill((4,0)--(10,0)--(10,6)--(4,6)--cycle, gray(.7));
draw((0,0)--(10,0));
draw((0,2)--(10,2));
draw((0,4)--(10,4));
draw((0,6)--(10,6));
draw((0,8)--(10,8));
draw((0,10)--(10,10));
draw((0,0)--(0,10));
draw((2,0)--(2,10));
draw((4,0)--(4,10));
draw((6,0)--(6,10));
draw((8,0)--(8,10));
draw((10,0)--(10,10));
label("1",(1,9));
label("2",(3,9));
label("3",(1,7));
label("4",(3,7));
\end{asy}

