size(5cm);defaultpen(fontsize(9));
pair o = (0, 0); pair q = (0, 12); pair b = (12, 0);
pair a = (2, 12);

draw((-2, 0)--(15, 0), Arrow);
draw((0, -2)--(0, 15), Arrow);
draw(q--a--b);

label("$Q(0, 12)$", q, W);
label("$A(2, 12)$", a, NE);
label("$B(12, 0)$", b, S);
label("$O(0, 0)$", o, SW);
label("$x$", (15, 0), E);
label("$y$", (0, 15), N);

[/asy]

