problem:
Let $ABCD$ be a rectangle.  Let $E$ and $F$ be points on $BC$ and $CD$, respectively, so that the areas of triangles $ABE$, $ADF$, and $CEF$ are 8, 5, and 9, respectively.  Find the area of rectangle $ABCD$.

[asy]
unitsize(1.5 cm);

pair A, B, C, D, E, F;

A = (0,2);
B = (0,0);
C = (3,0);
D = (3,2);
E = (3*B + 2*C)/5;
F = (2*D + C)/3;

draw(A--B--C--D--cycle);
draw(A--E--F--cycle);

label("$A$", A, NW);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, NE);
label("$E$", E, S);
label("$F$", F, dir(0));
label("$8$", (A + B + E)/3);
label("$5$", (A + D + F)/3);
label("$9$", (C + E + F)/3);
[/asy]

