draw(O--P, dashed);
label("A", A, NW);
label("B", B, NE);
label("C", C, SE);
label("D", D, SW);
label("O", O, S);
label("P", P, N);
label("12", (D+O)/2, S);
label("12", (O+C)/2, S);
label("10", (A+D)/2, NW);
label("10", (B+C)/2, NE);
[/asy]

