label("$C$", (0,0), SW);
label("$D$", (0,5), NW);
label("1",(.5,5), N);
label("1",(1,4.5), E);
label("1",(4.5,1), N);
label("1",(4,.5), E);
label("3",(1,2.5), E);
label("3",(2.5,1), N);
[/asy]

